add(1,'Versiuni, acoperire funcțională și oracol fiscal datat',['P01.C06','P01.C13','P01.C15','P01.C16'],['A03.PL01','A03.PL04'],['@AGENTS.md','@Documentatie/echipa-2026-10-09/00_REGULI_TESTARE.md','@Documentatie/echipa-2026-10-09/00_CAPITOLE_PROIECTE.json','fiscal/ParametriFiscali.java','fiscal/JurnalVersiuniModel.java'],['AD_System','AD_Client','AD_Org','AD_Process','AD_Form','AD_Window','AD_Table','AD_Column'],['Manifest Git actual; inventar bundle/config instalat separat; set de documente la două date de valabilitate fiscală.'],['Înregistrează Git, build, DB și bundle-uri în manifest distinct; explică orice diferență.','Inventariază toate procesele/formele/declarațiile contabile din AD și cod, inclusiv joburi fără meniu; stabilește totaluri și orfani.','Pentru fiecare regulă fiscală, citește sursa oficială și versiunea normei/XSD/validatorului la data operației, cu dată intrare în vigoare și amendamente.','Construiește oracolul independent de implementare; leagă fiecare formulă/cotă/dată de sursă oficială.'],['Zero mecanisme/declarații/forme contabile fără titular și control; total extras reconciliat cu inventarul A12/A09/A02.','100% regulilor fiscale testate au sursă oficială, interval de valabilitate și parametru/config corespunzător; fără afirmație legală actuală din memorie.','Git SHA și installed version sunt câmpuri independente; necunoscut rămâne explicit.'],['Versiune instalată diferită de Git; regulă fără sursă; cotă lipsă sau două intervale suprapuse; validator vechi pentru perioadă nouă.'],['AD Dictionary','C_AcctSchema','C_Tax','C_Period'], 'Utilizatorul vede perioada/configurația folosită și un mesaj acționabil pentru sursă/parametru lipsă; nicio etichetă de succes înaintea verificării.', ['A03-A02','A03-A09','A03-A10','A03-A12']);
add(2,'Izolare cabinet, firmă, organizație și schemă în contabilitate',['P01.C01','P01.C13','P01.C19','P01.C20'],['A03.PL01','A03.PL03'],['date/BalantaService.java','form/WBalantaForm.java','process/RegistruJurnal.java','audit/JurnalAudit.java'],['AD_Client','AD_Org','AD_Role','C_AcctSchema','Fact_Acct','GL_Journal'],['Firme A/B cu DocumentNo identic, cont identic dar solduri diferite 100 și 700; două organizații; utilizator cu acces numai A.'],['Generează balanță/fișă/export pe A; salvează parametrii și interogarea finală.','Schimbă firma/org în UI; verifică cache, detalii, export și linkul documentului.','În clonă testează ID B introdus în cererea/procesul autorizat pe A; verifică autorizarea pe server.','Compară numărul și soldul rândurilor UI/DB/export în aceeași dată și schemă.'],['Niciun rând/sumă/denumire/URL din B în rezultatul lui A; soldul 700 nu contaminează 100.','Fiecare înregistrare urmărită are AD_Client_ID/AD_Org_ID/schemă corecte; interdicția există pe server.','Schimbarea contextului invalidează datele și selecția precedentă.'],['ID ghicit; sesiune cu firmă schimbată; export async din context vechi; rol fără acces; firmă cu CUI similar; organizația * confundată cu toate.'],['AD_Role/AD_Org access','MRole','C_AcctSchema'], 'Antet persistent cabinet/firmă/org/perioadă; schimbare context fără raport învechit; mesaj explicit de acces refuzat.', ['A03-A01','A03-A02','A03-A09']);
add(3,'Plan de conturi, dimensiuni și monografie configurată',['P01.C01','P01.C12'],['A03.PL01'],['fiscal/MutareContMotor.java','fiscal/RegulaContFacturaEmisa.java','monografie/JurnalDosar.java'],['C_Element','C_ElementValue','C_ValidCombination','C_AcctSchema_Element','C_AcctSchema_Default','Fact_Acct'],['Cont sintetic/analitic, cont inactiv, cont cu interval de valabilitate, două dimensiuni organizaționale și schemă secundară.'],['Leagă regula de monografie de document și combinația contabilă efectivă.','Calculează în oracol independent conturile/dimensiunile așteptate pentru aceleași tranzacții.','Verifică selecția UI și server pentru cont inactiv/sintetic nepostabil sau dimensiune lipsă.','Repostează doar în clonă folosind configurație schimbată și urmărește politica istorică/revizie.'],['100% liniilor au cont și dimensiuni conform regulii aprobate; echilibrul singur nu produce PASS.','Modificarea parametrilor nu rescrie tacit istoricul; fiecare utilizare are versiune/referință.'],['Cont inactiv; schemă neconfigurată; mapare incompletă; cont de alt client; mutare cont cu documente postate.'],['C_ValidCombination','C_AcctSchema_Element','Product/BusinessPartner/Tax accounting defaults'], 'Selectoare cu context și explicații pentru cont obligatoriu; acces rapid la document și regulă, fără coduri tehnice neexplicate.', ['A03-A02','A03-A09']);
add(4,'Nota contabilă: DocAction, commit și postare reală',['P01.C01','P01.C12'],['A03.PL01'],['process/RestaureazaNoteSuspendate.java','component/EvaAuditPostareEvents.java','monografie/JurnalDosar.java'],['GL_JournalBatch','GL_Journal','GL_JournalLine','AD_PInstance','Fact_Acct'],['Notă 100 debit/100 credit; variantă dezechilibrată 100/99; document cu validare respinsă; document pregătit dar non-CO.'],['Urmărește UI→AD_Process/AD_PInstance→PO nativ→processIt/DocAction→save/commit.','Citește DocStatus/Processed/Posted și eroarea după commit, apoi rândurile Fact_Acct pe cheia documentului și schemă.','Rulează același buton de 2–3 ori și două solicitări concurente în clonă.','Testează eșec înainte/după completare și înainte de confirmarea UI, apoi reluare.'],['CO, postat și reconciliat sunt stări distincte; processIt=true singur nu este succes.','O singură postare economică pe document/schemă; documentul dezechilibrat nu devine postat.','Starea non-CO rămâne vizibilă și nu este declarată finalizată; rollback nu lasă linii orfane.'],['IP/WP/WC/invalid; timeout după commit; dublu click; CO cu postare eșuată; lipsă cont.'],['MJournal/MJournalLine','DocAction','DocumentEngine','Fact/Fact_Acct posting engine'], 'Mesajul separă salvare/completare/postare; se afișează cauza și reluarea permisă fără duplicare.', ['A03-A02','A03-A09']);
add(5,'Echilibru Fact_Acct, proveniență și semnificația zero net',['P01.C01','P01.C12'],['A03.PL01','A03.PL02','A03.PL03','A03.PL06'],['component/EvaAuditPostareEvents.java','date/BalantaService.java','process/BalantaVerificare.java'],['Fact_Acct','AD_Table','C_AcctSchema','C_ElementValue','GL_Journal','C_Invoice','M_InOut'],['Document normal, stornat, nepostat, și pereche de linii +100/-100 cu total net zero.'],['Construiește identificator AD_Table_ID/Record_ID/Line_ID și păstrează fiecare schemă/PostingType separat.','Verifică debit=credit în moneda schemei și valuta documentului conform politicii native.','Reconstituie contul, organizația și sensul fiecărei linii, nu numai suma finală.','Compară rânduri și sume înainte/după postare/reversare/repostare cu raportul.'],['Diferența debit-credit este exact zero la precizia monetară definită pentru fiecare grup document/schemă/PostingType.','Zero net nu este interpretat zero rânduri sau lipsă efect; fiecare linie are proveniență validă.','Zero documente raportate drept postate fără dovadă; zero Fact_Acct orfane în fixture.'],['Document din alt client; duplicare echilibrată debit/credit; conturi greșite dar total corect; lipsa unei scheme; Posted=Y fără rândurile așteptate.'],['Fact_Acct','native posting engine','C_AcctSchema'], 'Drill-down din sold la rând și document, cu schemă/monedă și status clar; număr de rânduri afișat corect.', ['A03-A02','A03-A05','A03-A07']);
add(6,'Monedă, rotunjiri și date document/contabilizare/curs',['P01.C01','P01.C04','P01.C05'],['A03.PL02','A03.PL03'],['corelare/CursBnrFactura.java','form/WSagaJurnalValutaForm.java','banca/MotorContare.java'],['C_Currency','C_ConversionType','C_Conversion_Rate','C_Invoice','C_Payment','C_AllocationHdr','Fact_Acct'],['3 linii la 0,335 cu 3 zecimale preț, cantități fracționare, monedă 2 zecimale și monedă 0 zecimale; DateInvoiced/DateAcct/DateTrx diferite; cursuri sintetice 4,9 și 5,1.'],['Fixează independent politica liniilor/taxelor/totalului și precizia fiecărei monede.','Calculează factura și plata la date/cursuri diferite; urmărește diferența de curs în documentele native.','Verifică selecția cursului și sursa/datele salvate, apoi exporturile și Fact_Acct.','Testează curs lipsă/invers, weekend și limită lună/an fără fallback nedocumentat.'],['Totalurile coincid exact după aceeași regulă aprobată de rotunjire; nu se folosește toleranță universală 0,01.','Diferența realizată de curs apare o singură dată în contul și perioada corecte; moneda documentului nu este înlocuită tacit.','DateAcct/perioada sunt independente și vizibile față de data documentului/cursului.'],['Curs zero/negativ/lipsă; intervale suprapuse; valori foarte mari; credit note negativ; valută fără curs; conversie dublă.'],['MConversionRate','C_Currency precision','native invoice/payment/allocation posting'], 'Etichete explicite pentru date și monede; afișare concordantă UI/PDF/export; eroarea indică exact cursul lipsă.', ['A03-A02','A03-A07','A03-A09']);
add(7,'Factura: net/brut, taxe, discount și transport integral',['P01.C05','P01.C10'],['A03.PL02'],['fiscal/DiscountFactura.java','fiscal/RegimFiscalFactura.java','fiscal/GardaFacturaL4a.java','fiscal/GardaFacturaL4b.java','documente/date/DateFactura.java'],['C_Order','C_OrderLine','C_Invoice','C_InvoiceLine','C_InvoiceTax','C_Tax','M_PriceList'],['Coș mixt cu două cote configurate τ1/τ2, produs scutit, discount linie/document, taxă transport și preț inclus/exclus TVA; bill-to diferit de ship-to.'],['Preia contractul canonic de la A06/A08 și identifică maparea fiecărui câmp în comandă/factură.','Calculează independent net/taxă/brut pe linie și document potrivit config/sursei fiscale datate.','Urmărește factura finală și postingul după livrare parțială, retur și credit note.','Compară UI, print, XML și DB; repetă importul fără duplicare.'],['Net + taxe + transport − discount, aplicate o singură dată, reconciliază GrandTotal conform oracolului.','Bill-to/ship-to, moneda, cota/regimul și referințele nu sunt pierdute ori înlocuite cu valori generice.','Factura parțială acoperă exact cantitățile și sumele admise, nu totalul comenzii la fiecare expediere.'],['Lipsă regim/cotă; preț inclus tratat exclus; discount negativ/100%; retur parțial; taxă transport dublă; monedă incompatibilă.'],['MInvoice/MInvoiceLine/MInvoiceTax','MOrder','MPriceList','C_Tax'], 'Utilizatorul poate vedea calculul și sursa prețului/taxei; erorile păstrează datele introduse.', ['A03-A06','A03-A07','A03-A08','A03-A09']);
add(8,'Parametri fiscali și vector: intervale, revizii, explicabilitate',['P01.C06','P01.C07','P01.C08'],['A03.PL04','A03.PL05','A03.PL06'],['fiscal/ParametriFiscali.java','fiscal/ParametriModel.java','fiscal/VectorFiscalModel.java','fiscal/CoroborareVectorFiscal.java','form/WSagaParametriFiscaliForm.java','form/WSagaVectorFiscalForm.java'],['C_Tax','AD_ClientInfo','AD_PInstance','EVA: tabelele efective ale registrului fiscal se inventariază cu A02'],['Două intervale alăturate, o lacună, o suprapunere; firmă cu schimbare de regim în cursul anului; istoric deja declarat.'],['Inventariază toate citirile de cote/praguri și caută valori hardcodate după gate.','Leagă fiecare parametru de firmă/perioadă/regim, sursă oficială, aprobare și revizie.','Recalculează documente înainte/la/după limită folosind versiunea aplicabilă.','Schimbă parametru în clonă și verifică politica documentelor și declarațiilor istorice.'],['Fiecare dată/regim selectează exact o versiune validă sau se oprește cu eroare; zero fallback fiscal tacit.','Parametrul nou nu rescrie istoric fără operație explicită și auditabilă; revizia veche rămâne reproductibilă.'],['Suprapunere; lipsă parametru; client greșit; lege viitoare aplicată retroactiv; cache de valori vechi.'],['C_Tax effective dates','AD configuration/process framework'], 'Listă clară de setări pe categorie, validitate și sursă; schimbările cu impact arată documentele/perioadele afectate.', ['A03-A02','A03-A09']);
add(9,'Jurnale TVA: regimuri și reconciliere document–taxă–cont',['P01.C05','P01.C06'],['A03.PL02','A03.PL04'],['date/JurnalTvaService.java','process/JurnalTVA.java','form/WSagaJurnaleTvaForm.java','fiscal/TvaMarja.java','component/EvaTvaMarjaEvents.java'],['C_Invoice','C_InvoiceLine','C_InvoiceTax','C_Tax','Fact_Acct'],['Vânzare/cumpărare internă, taxare inversă, operație UE, scutită, TVA la încasare și marjă numai dacă aplicabile conform oracolului oficial.'],['Definește matrice regim×tip document×perioadă×cotă din surse oficiale, fără presupunerea că toate firmele aplică tot.','Urmărește baza/taxa din factura originală până la jurnal și conturile fiscale.','Repetă cu credit note, schimbare regim și document antedatat.','Reconciliază pe regim/cotă/partener cu declarația, explicând diferențele legale de perioadă.'],['100% documentelor eligibile apar exact o dată în jurnalul corect; excluderile sunt explicite.','Baza/taxa și conturile se potrivesc oracolului; fiecare diferență jurnal/declarație are justificare trasabilă.'],['Taxă zero confundată cu scutire; cod de taxă greșit; marjă negativă; import UE fără date; schimbare perioadă.'],['C_InvoiceTax','C_Tax','Fact_Acct','native tax posting'], 'Jurnalul explică regimul și documentele excluse; drill-down și filtre păstrează același total.', ['A03-A04','A03-A09']);
add(10,'TVA la încasare și solduri preluate: alocare parțială/storno',['P01.C04','P01.C06','P01.C11'],['A03.PL03','A03.PL04'],['fiscal/RegistruTvai.java','fiscal/SoldTvaNeexigibilPreluat.java','process/ReglareTvaNeexigibilaPreluat.java','corelare/MotorCorelare.java'],['C_Invoice','C_Payment','C_AllocationHdr','C_AllocationLine','Fact_Acct'],['Factură 1000 brut, plăți 600 și 400; alternativ avans 200 + diferență 800; sold importat cu TVA neexigibilă și o alocare anulată.'],['Obține oracolul legal de exigibilitate și rotunjire pentru datele fixture-ului.','Urmărește native allocation și recunoașterea fiscală proporțională după fiecare plată.','Anulează/reversează alocarea 600 în clonă și recreeaz-o; repetă mesajul de plată.','Compară soldurile inițiale/preluate cu jurnalul și Fact_Acct, fără dublarea recunoașterii.'],['Soldul comercial este 400 după prima plată și 0 după a doua; taxa recunoscută urmează oracolul cu diferență finală de rotunjire tratată explicit.','Retry/storno/realocare nu multiplică TVA; preluarea inițială nu recunoaște încă o dată soldul fiscal.'],['Plată parțială peste sold; alocare de alt client; taxă alocată de două ori; sold fiscal lipsă; anulare după perioadă închisă.'],['MAllocationHdr/MAllocationLine','native allocation posting','C_Invoice open amounts'], 'UI separă încasat, alocat și exigibil; prezintă documentele și proporția care justifică taxa.', ['A03-A04','A03-A07','A03-A02']);
add(11,'Încasări, plăți, avansuri și reconciliere financiară',['P01.C04','P01.C10'],['A03.PL03'],['banca/MotorContare.java','corelare/MotorCorelare.java','corelare/MotorStripe.java','setup/PostareDirectaTrezorerie.java','form/WSagaJurnalCasaBancaForm.java'],['C_Payment','C_AllocationHdr','C_AllocationLine','C_BankStatement','C_BankStatementLine','C_Invoice','Fact_Acct'],['Factură1000; încasări600/400; avans200; comision30; două expedieri300/700; o rambursare150 și un extras duplicat.'],['A07 furnizează evenimentul de plată/decontare și cheia de idempotency; verifică semnificația brut/net/comision.','Urmărește documentele native payment/allocation/bankstatement și conturile de tranzit până la sold reconciliat.','Testează alocare parțială, refund, inversarea ordinii evenimentelor și anulare.','Reconciliază brut=comision+net pentru decontare și factura=plăți alocate+sold, fără confundarea extrasului cu o a doua plată.'],['O singură creanță și o singură plată pe eveniment; avansul200 reduce diferența la800.','Ramburs per expediție nu repetă GrandTotal1000; comisionul30 nu reduce nejustificat suma datorată de client.','Conturile de tranzit au sold explicat pe evenimente deschise și se sting numai cu dovada corespunzătoare.'],['Timeout după commit; webhook duplicat; sumă/monedă nepotrivită; comision lipsă; refund înainte de payment; sursă nesemnată.'],['MPayment','MAllocationHdr/Line','MBankStatement/Line','bank matching/reconciliation'], 'Stări distincte primit/alocat/decontat/rambursat; utilizatorul vede diferența și remedierea fără a crea plată duplicată.', ['A03-A07','A03-A02','A03-A09']);
add(12,'Achiziții: recepție–factură–cost–plată și matching nativ',['P01.C03','P01.C04','P01.C05'],['A03.PL07'],['process/NoteStocuri.java','fiscal/MotorStraturi.java','corelare/ReguliPostareInventar.java'],['C_Order','M_InOut','M_InOutLine','C_Invoice','C_InvoiceLine','M_MatchInv','M_MatchPO','M_CostDetail','Fact_Acct'],['Comandă10 unități×10; recepții6+4; factură8 unități×11 și apoi2×11; cheltuieli de import separate; retur2.'],['A04 produce contractul cantități/preț/curs/cheltuieli și documentele sursă; A05 confirmă stratul/costul fizic.','Urmărește recepția, invoice și matching nativ până la conturile intermediare/cost.','Compară independent diferențe de cantitate/preț și costul repartizat după politica schemei.','Testează factură înainte de recepție, matching parțial și retur fără factură asociată.'],['Cantități matched≤recepționat/facturat conform contractului; cantitatea10 nu devine16 prin retry.','Diferența de preț și cheltuielile intră o singură dată în cost/conturile definite; soldurile intermediare sunt explicate.'],['Preț/valută diferite; lipsă cost; matching repetat; recepție non-CO; cost în perioadă închisă; anulare numai una dintre laturi.'],['MInOut','MInvoice','M_MatchInv','M_MatchPO','MCostDetail'], 'UI permite urmărit relația comandă–recepție–factură–diferențe; mesajul de matching nu confundă completat cu postat.', ['A03-A04','A03-A05','A03-A02']);
add(13,'G1/G2/G3, CPP/CPA: bun unic, consum unic și identități distincte',['P01.C03','P01.C10','P01.C17','P01.C18'],['A03.PL08'],['wms/RegistruWms.java','fiscal/MotorStraturi.java','process/NoteStocuri.java','corelare/ReguliPostareInventar.java'],['M_Product','M_Warehouse','M_Locator','M_StorageOnHand','M_Transaction','M_CostDetail','M_Production','Fact_Acct','EVA: mapping CPP/CPA/G1/G2/G3 de inventariat cu A02/A05'],['P1/P2/P3 câte120 în CPP/G1; S1=6+6+6→20 și S2=3+3+3→40 alternative G3; identități CPA distincte; multi-G1 10+10 și rezervare7→13 global.'],['Urmărește proprietarul contabil G1 și reprezentarea fizică G2, până la monografia și Fact_Acct.','Asamblează în clonă o operație G2 cu cutieA1 și manoperă0,5h; repetă același ID operație.','Dezasamblează și reasamblează fizic ca operație nouă, cu noi locatori; verifică consumurile reale.','A05 dovedește cantitățile/forma/ASI-MA/genealogia; A03 verifică numai efectele contabile și costul unic.'],['G1+G2+G3 nu se adună ca trei active; P1/P2/P3 rămân bunurile contabile iar S1/S2 sunt alternative ce concurează pentru aceleași componente.','CPP și CPA au ID/cod permanent distinct; SKU/EAN nu înlocuiește identitatea.','Cutia și costurile se înregistrează o singură dată în G1 per operație fizică; retry nu dublează, operația fizică nouă poate consuma resurse noi.','Setul CPA dezasamblabil nu creează stoc contabil suplimentar; transformarea reală eligibilă se separă explicit și poate folosi producția nativă.','Rezervarea7 se scade o singură dată global:10+10−7=13.'],['Toate componentele sunt asamblate S1; comandă piese necesită dezasamblare; două operații concurente; ASI0 valid prin MA; cost manoperă deja în salarii; anulare parțială.'],['M_Product identity','M_Warehouse/M_Locator','M_Production numai pentru transformare contabilă reală','native costing/transactions; fără registru paralel de stoc'], 'Etichete distincte G1 contabil/G2 fizic/G3 disponibil pentru vânzare, CPP/CPA și operație/retry; cantitățile alternative nu apar totalizate ca stoc suplimentar.', ['A03-A05','A03-A02','A03-A06','A03-A09']);
add(14,'Straturi, inventariere, transfer și ajustări de valoare',['P01.C03','P01.C08','P01.C17','P01.C18'],['A03.PL08'],['fiscal/MotorStraturi.java','corelare/ReguliPostareInventar.java','process/BalantaStocuri.java','fiscal/NoteObiecteInventar.java'],['M_Inventory','M_InventoryLine','M_Movement','M_MovementLine','M_Transaction','M_CostDetail','M_AttributeSetInstance','Fact_Acct'],['Două straturi6×10 și4×12, numărare9 versus stoc10; transfer între doi locatori și între două G1; deteriorat/tranzit/rezervat separat.'],['A05 furnizează inventariere în ciornă, aprobare și ajustare nativă distincte; urmărește momentul apariției efectului contabil.','Compară costul așteptat după metoda schemei cu straturi, M_CostDetail și Fact_Acct.','Testează transfer/reversare și numărare importată de două ori, verificând dacă importul creează sau actualizează efectiv.','Verifică ASI/MA și stările de calitate/tranzit fără interpretarea ASI0 ca lipsă universală.'],['Numărarea în ciornă nu produce ajustare; ajustarea validată produce exact diferența−1 în fixture.','Transferul intern nu dublează bunul/valoarea; diferențele permise între organizații sunt explicate în schema contabilă.','Valoarea balanței stocului se reconciliază pe produs/org/costing; zero net nu ascunde rânduri duble.'],['ImportInventory presupus upsert; postare eșuată; inventar de alt org; cost lipsă; strat negativ; rotație/retry/intrerupere.'],['MInventory','MMovement','MCostDetail','M_Transaction','ASI/MA'], 'Numărat, diferență, aprobat și postat sunt stări vizibile; avertizarea nu permite confundarea importului cu ajustarea.', ['A03-A05','A03-A02','A03-A09']);
add(15,'Preînchidere lună: documente nepostate și perioade deschise',['P01.C02'],['A03.PL09'],['fiscal/InchidereLuna.java','process/StareInchidereLuna.java','form/WSagaGhidInchidereForm.java','form/WSagaInchidereLunaForm.java'],['C_Period','C_PeriodControl','C_Year','C_AcctSchema','AD_PInstance','Fact_Acct'],['Lună cu factură CO nepostată, plată nealocată, jurnal dezechilibrat, inventar non-CO, parametru fiscal lipsă și document valid.'],['Inventariază precondițiile pe toate tipurile documentelor și schemele contabile aplicabile.','Rulează verificarea în clonă și compară lista de blocaje cu fixture-ul independent.','Accesează fiecare blocaj, corectează în clonă și reexecută verificarea.','Încearcă postare DateAcct închisă versus data documentului în lună deschisă.'],['100% blocajelor fixture-ului apar cu document/firmă/perioadă; închiderea nu continuă peste blocaje obligatorii.','Perioada se decide după DateAcct și DocumentBaseType conform configurației native; nu numai după data documentului.','Raportul nu numește închisă o lună cu documente eligibile nepostate.'],['Org/schemă secundară omisă; document creat în timpul verificării; parametri lipsă; rol fără acces la remediere; timeout.'],['MPeriod/MPeriodControl','native period control','DocAction posting'], 'Checklist de preînchidere cu link la document și responsabil; avertizările sunt separate de blocaje.', ['A03-A02','A03-A09']);
add(16,'Închidere/reînchidere/reluare: idempotency și concurență',['P01.C02'],['A03.PL09'],['fiscal/InchidereLuna.java','fiscal/NotaInchidere.java','fiscal/TipNotaInchidere.java','process/InchidereProgramata.java','component/EvaNoteInchidereEvents.java'],['C_PeriodControl','GL_Journal','GL_JournalLine','Fact_Acct','AD_PInstance'],['Aceeași firmă/lună/schemă, două clickuri concurente și job programat; întrerupere după creare jurnal înainte de răspuns.'],['Identifică cheia operației și granița tranzacției pentru fiecare etapă a închiderii.','Execută în clonă normal, retry, concurent și recuperare după întrerupere.','Reopen autorizat și document întârziat; urmărește anularea/înlocuirea notelor precedente conform politicii.','Compară înregistrările, documentele și statusul perioadei la fiecare etapă.'],['Cel mult un set economic activ de note per firmă/perioadă/schemă/etapă; retry nu creează un al doilea set.','Starea finală și mesajul UI coincid cu documentele persistate; rollback/recuperare nu lasă lună marcată închisă incomplet.','Reînchiderea păstrează trasabilitatea notelor vechi și noilor documente.'],['Job și UI simultan; deadlock; cont lipsă la mijloc; întrerupere postare; nouă factură între precheck și lock; reopen neautorizat.'],['MJournal','DocAction reversal','MPeriodControl','transaction/locking native'], 'Pașii și progresul sunt vizibile; buton reluare sigur; nu se blochează definitiv interfața după eroare.', ['A03-A02','A03-A10','A03-A09']);
add(17,'Note de închidere venituri/cheltuieli/TVA și rezultat',['P01.C01','P01.C02','P01.C06'],['A03.PL09'],['process/InchidereVenituri.java','process/InchidereTVA.java','fiscal/ContInchidereCV.java','fiscal/NotaInchidere.java'],['GL_Journal','GL_JournalLine','Fact_Acct','C_ElementValue','C_AcctSchema'],['Venit1000, cheltuială700, corecție−50 pe venit, TVA conform oracolului și două scheme; solduri inițiale distincte de rulaj.'],['Calculează independent rezultatul950−700=250 înainte de impozit pentru fixture-ul sintetic.','Urmărește conturile selectate, excluderile și formula sursă→nota→Fact_Acct.','Verifică închiderea TVA separat de exigibilitate și de declarație.','Reexecută/reversează și compară balanța înainte/după inclusiv soldurile inițiale.'],['Conturile și dimensiunile sunt corecte, nu doar debit=credit; rezultatul fixture-ului este250 înainte de tratamentul fiscal separat.','Solduri/rulaje nu se dublează și luna închisă corespunde DateAcct.','Diferența TVA reflectă oracolul fiscal și nu se presupune automat egală decontului fără reconciliere.'],['Cont de închidere lipsă; notă precedentă inclusă din nou; venit cu semn negativ; altă schemă; sold istoric numărat ca rulaj.'],['MJournal/GL_JournalLine','Fact_Acct aggregation','native account hierarchy'], 'Previzualizare cu sursă, formulă și cont de rezultat; drill-down pentru fiecare sumă.', ['A03-A02','A03-A09']);
add(18,'Balanță, jurnal, fișă cont și bilanț: oracol independent',['P01.C01','P01.C09','P01.C12'],['A03.PL01','A03.PL09'],['date/BalantaService.java','process/BalantaVerificare.java','process/BalantaAnalitica.java','process/RegistruJurnal.java','form/WRegistruForm.java','form/WSagaRegistruJurnalForm.java','form/WSagaBilantForm.java','anaf/GenBilant.java'],['Fact_Acct','C_ElementValue','C_AcctSchema','GL_Journal'],['Sold inițial debit100, mișcări debit50/credit30, sold final120; cont analitic plus părinte, document stornat, perioadă fără mișcare.'],['Construiește tabel independent din documentele fixture-ului și reconcilierea cu Fact_Acct pe schemă/PostingType/perioadă.','Compară jurnal, fișă cont, balanță analitică/sintetică și bilanț, inclusiv conturi fără mișcare.','Aplică filtre org/perioadă/cont și verifică numitorul rândurilor și totalurile înainte/după paginare.','Verifică mapările bilanțului și sursa oficială a formularului în vigoare pentru anul raportat.'],['Sold final=inițial+debit−credit cu orientarea corectă a contului; fixture120.','Părintele însumează exact analiticele eligibile fără a aduna încă o dată părinții.','100% rubricilor bilanțului au formulă/mapare verificabilă și versiune de formular oficială; totaluri UI=export=raport.'],['Filtru dată exclusiv/inclusiv; cont fără mișcare; închideri incluse de două ori; sold creditor negativ afișat debit; cont necartografiat.'],['Fact_Acct','C_ElementValue hierarchy','native report/print format'], 'Explicarea soldurilor și filtrelor, acces la detalii, totaluri fixe vizibile și export complet cu aceiași parametri.', ['A03-A02','A03-A09']);
add(19,'D300/D390/D394: surse, revizii, validator oficial și corelări',['P01.C06'],['A03.PL04'],['anaf/GenD300.java','anaf/GenD390.java','anaf/GenD394.java','anaf/ComparatorDeclaratii.java','fiscal/D394Reguli.java','form/WSagaD205Form.java','form/WSagaHartaDeclaratiiForm.java'],['C_Invoice','C_InvoiceTax','C_BPartner','Fact_Acct','AD_PInstance','EVA: registru declarații de inventariat'],['Perioadă cu facturi normale/corecții, două cote/regimuri, partener UE, firmă fără activitate și o corecție după generare.'],['Stabilește din sursa ANAF formularul/XSD/validatorul și instrucțiunile valabile perioadei; salvează hash.','Reconciliază fiecare rubrică cu jurnalul și documentele, păstrând explicații pentru diferențele permise între declarații.','Generează XML/PDF în clonă; validează offline oficial unde disponibil, fără depunere.','Regenerare și rectificare după modificare: compară versiuni, păstrează originalul și aprobarea.'],['100% rubricilor populate au proveniență; totaluri egale cu oracolul, cu rotunjirile oficiale explicite.','XML respectă schema/validatorul aplicabil; eroare de validator nu este PASS; generat/validat/depus/recipisă sunt stări distincte.','Acoperire distinctă per declarație și perioadă, nu un singur test extrapolat la toate.'],['Partener lipsă CUI; lună greșită; cote mixte; document stornat; schemă ANAF veche; generare duplicată; activitate zero.'],['Native invoices/taxes/Fact_Acct ca sursă; EVA declarative mapping existent înaintea oricărui motor nou'], 'Harta declarațiilor explică obligațiile, sursa, erorile pe rubrici/documente și versiunea validatorului; fără buton care sugerează depunere efectuată.', ['A03-A02','A03-A09','A03-A10']);
add(20,'D100/D101/D205 și bilanț anual: obligație versus generare',['P01.C01','P01.C06'],['A03.PL04','A03.PL09'],['anaf/GenD100.java','anaf/GenD101.java','anaf/GenD205.java','anaf/GenBilant.java','anaf/SabloaneBilant.java','anaf/AcoperireDeclaratii.java','fiscal/RegistruAsociati.java','fiscal/RegistruRetineri.java'],['Fact_Acct','C_BPartner','C_Period','AD_PInstance','EVA: vector fiscal/registru rețineri/declarații de inventariat'],['Firmă cu obligație trimestrială/anuală, schimbare regim, beneficiar cu reținere, an fiscal diferit dacă suportat și perioadă fără obligație.'],['Leagă vectorul/regimul/datele de obligația legală verificată oficial, nu de simpla existență a generatorului.','Calculează independent bază, ajustări deductibil/nedeductibil, rețineri și rubrici aplicabile.','Compară datele sursă cu declarație, bilanț și nota contabilă unde există.','Validează offline schema și scenariul fără obligație; verifică versiuni/corrections.'],['Nicio obligație este creată ori omisă numai pe baza existenței unui buton; toate regulile au sursă și valabilitate.','Toate ajustările fiscale sunt explicate față de rezultatul contabil; generatorul nu confundă profit contabil cu bază impozabilă.','Datele beneficiarilor sunt minimizate în dovezi.'],['Prag schimbat; perioadă parțială; beneficiar duplicat; rectificativă; parametru absent; formular vechi.'],['Fact_Acct/native period/account dimensions','EVA fiscal parameters/registries reutilizate'], 'Obligație, termen, perioadă și motiv sunt clare; lipsurile sunt navigabile către sursă, nu mascate prin zero.', ['A03-A02','A03-A09']);
add(21,'D406 SAF-T: master data, tranzacții și reconciliere de volum',['P01.C06','P01.C11'],['A03.PL04'],['anaf/GenD406.java','anaf/saft/CoduriTvaSaft.java','anaf/RegistruDeclaratii.java'],['C_ElementValue','C_BPartner','M_Product','C_Tax','Fact_Acct','C_Invoice','C_Payment','M_InOut','A_Asset'],['Perioadă cu note, facturi, plăți, stoc și active; identificatori repetabili, diacritice, caractere XML și volum mare; subraport stoc/active dacă aplicabil.'],['Inventariază secțiunile cerute de instrucțiunea oficială pentru tipul perioadei/obligației.','Reconciliază master data și tranzacții pe chei, conturi, taxe, cantități și sume, cu numitori expliciți.','Generează și validează offline XSD/validatorul oficial aplicabil, fără depunere.','Testează streaming/paginare și întrerupere la pragul de fișier; regenerează și compară conținutul normalizat.'],['Zero referințe orfane; 100% tranzacțiilor eligibile exact o dată; totaluri concordante cu sursele și Fact_Acct.','Exportul complet nu se limitează la pagina UI; întreruperea nu produce fișier prezentat drept valid complet.','Validatorul și hashul fiecărei părți rămân în registru.'],['TVA nemapat; Unicode/XML invalid; cont/partener absent; duplicate la paginare; anulare/storno; memorie insuficientă.'],['Native master-data/document identifiers','Fact_Acct','EVA SAF-T generator existent'], 'Progres și număr documente/secțiuni; eroare localizată; descărcare doar pentru artefact complet și identificabil.', ['A03-A02','A03-A04','A03-A05','A03-A10']);
add(22,'e-Factura primită: document original, deduplicare și înregistrare',['P01.C05','P01.C09'],['A03.PL02','A03.PL10'],['efactura/DepozitEFactura.java','efactura/AsociereEFactura.java','efactura/ArhivaEFactura.java','process/EFacturaSync.java'],['C_Invoice','C_InvoiceLine','C_InvoiceTax','C_BPartner','AD_Attachment','EVA: coadă/depozit/asociere eFactura de inventariat'],['Două XML-uri cu același ID extern, unul retransmis, o corecție credit note și două firme cu număr factură identic.'],['A04 confirmă contractul de import; urmărește XML original→depozit→asociere→factură PO.','Verifică hash/id fiscal extern/client și politica de deduplicare; repetă evenimentul în mock.','Compară date originale, partener, document/date/cote/monedă/adrese și linii cu factura persistată.','Verifică atașamentul original și audit trail până la posting și jurnal.'],['Originalul se păstrează nemodificat; o singură factură asociată pentru aceeași identitate externă în același client.','Credit note rămâne document distinct legat de original; totalurile și regimurile se reconciliază.','Descărcat/asociat/completat/postat sunt stări separate.'],['XML trunchiat; zip invalid; identitate alt client; CUI contradictoriu; total invalid; sursă indisponibilă; document non-CO.'],['MInvoice/MInvoiceLine','AD_Attachment','native DocAction; adaptare depozit EVA existent'], 'Utilizatorul compară originalul și propunerea, vede diferențe și poate relua fără dublare.', ['A03-A04','A03-A02','A03-A09']);
add(23,'e-Factura emisă: coadă, credit note și recipisă fără efect extern',['P01.C05'],['A03.PL10'],['efactura/EFacturaCoada.java','efactura/UblRoCreditNote.java','process/EFacturaTrimite.java','process/EFacturaRaport.java','component/EvaFacturaEmisaNumarEvents.java'],['C_Invoice','C_InvoiceLine','C_InvoiceTax','AD_PInstance','EVA: coadă/recipisă eFactura de inventariat'],['Factură și credit note native; mock răspuns acceptat/respins/timeout după acceptare; două retry concurente.'],['Inspectează lanțul de generare și configurare, apoi activează garda fără egress; nu apelează SPV/ANAF.','Validează XML/UBL și legătura la factura exactă, versiunea/numărul/documentul original.','Injectează prin mock răspunsuri în ordine normală și inversă, timeout ambiguu și respingere.','Verifică coada, idempotency și reconcilierea recipisei fără schimbarea arbitrară a documentului contabil.'],['Zero apeluri externe de scriere; dovada este MOCK/LOCAL, niciodată depunere live.','Un document/versiune trimis logic o singură dată; timeout nu înseamnă automat respins și nu dublează.','Generat/validat/în coadă/trimis/acceptat/respins se bazează pe dovezi distincte; credit note are referința corectă.'],['Număr duplicat; recipisă alt document/client; retry după acceptare; XML invalid; certificat expirat simulat; stornare înainte de răspuns.'],['Native invoice/credit memo numbering and DocAction','EVA coadă/UBL existent'], 'Starea și următoarea acțiune sunt explicite; nu se arată acceptat ANAF doar fiindcă procesul local a returnat succes.', ['A03-A10','A03-A02','A03-A09']);
add(24,'e-Transport și e-TVA: obligații, legături și diferențe',['P01.C03','P01.C06'],['A03.PL04','A03.PL10'],['efactura/ETransportClient.java','form/WSagaETransportForm.java','form/WSagaETvaForm.java','fiscal/ObligatiiETva.java'],['M_InOut','M_InOutLine','C_Invoice','Fact_Acct','EVA: registre eTransport/eTVA de inventariat'],['Transport aplicabil/neaplicabil conform regulii oficiale; date cantitate/greutate/vehicul incomplete; decont precompletat mock cu diferență explicabilă și una neexplicată.'],['Stabilește oficial obligația/versiunea pentru perioada fixture-ului; nu deduce obligația din existența meniului.','Urmărește aviz/transport/document și câmpurile obligatorii până la payload mock și registru.','Reconciliază eTVA cu jurnale/decont și clasifică fiecare diferență, păstrând sursa.','Testează corecție/anulare/expirare doar în mock, fără depunere/UIT real.'],['Zero declarații/UIT/corrections transmise extern; starea mock este distinctă de live.','Diferențele eTVA nu generează automat note contabile ori modificări de taxă fără proces justificat.','Legătura document–transport–obligație și fiecare diferență sunt explicabile.'],['Greutate/cantitate incorectă; UIT expirat simulat; duplicat; altă firmă; transport parțial; aviz CO confundat cu livrat.'],['MInOut/native shipment','native tax journals/Fact_Acct','EVA registre existente'], 'Utilizatorul vede aplicabilitatea, termenele, sursa și acțiunea necesară; tehnicul API nu înlocuiește explicația contabilă.', ['A03-A05','A03-A07','A03-A09','A03-A10']);
add(25,'Salarizare: contract datat, calcul, D112 și excepții',['P01.C07','P01.C06'],['A03.PL05'],['fiscal/MotorSalariiRO.java','fiscal/SimulareSalariu.java','process/CalculSalariiRO.java','process/PropuneExceptiiD112.java','anaf/GenD112.java','anaf/RubriciCmD112.java','form/WSagaCalculSalariiForm.java'],['EVA/AMN: contracte, payroll și detalii de confirmat în AD/schema instalată','AD_PInstance'],['Salariat sintetic lună completă/parțială, două contracte, concediu medical, suspendare, beneficiu/reținere și modificare salarială la mijlocul lunii.'],['Construiește oracol manual independent cu formule și parametri oficiali valabili fiecărei date.','Urmărește contract/pontaj/absențe→calcul→detalii salariale→D112, fără PII reală.','Recalculează după corecție și verifică istoricul/versiunile; validează D112 offline oficial.','Testează lipsa datelor obligatorii și deduceri/rețineri la limite fără fallback tacit.'],['Brut, contribuții, impozit, net și cost angajator coincid cu oracolul la precizia oficială.','Fiecare excepție D112 este justificată de document/regulă; recalcularea nu dublează persoana/perioada.','Generator/calculator/ecran/validator sunt dovedite separat, nu extrapolate dintr-un fixture simplu.'],['Contract suprapus; zile negative; CM cu cod invalid; parametru lipsă; două contracte cu plafon; recalcul după închidere.'],['Plugin payroll instalat efectiv, AMN_Payroll dacă disponibil','native periods/accounts; reutilizare motor EVA înainte de motor paralel'], 'Calcul explicabil pe salariat sintetic, erori legate de câmp/document, diferență față de luna precedentă și simulare distinctă de calcul final.', ['A03-A02','A03-A09']);
add(26,'Salarii în contabilitate, plată și manoperă G2 fără dublare',['P01.C07','P01.C01','P01.C03','P01.C04'],['A03.PL05','A03.PL08'],['process/InregistrareSalarii.java','process/CentralizatorSalarii.java','fiscal/ConturiSalarii.java','setup/SalarizareAuto.java'],['AMN_Payroll','AMN_Payroll_Detail','GL_Journal','GL_JournalLine','C_Payment','Fact_Acct'],['Stat salarial brut1000, rețineri300 și net700 configurate sintetic; centru cost G2 alocă manoperă100 din costul deja recunoscut, nu cheltuială nouă100.'],['Leagă versiunea finală stat/centralizator de nota contabilă și obligațiile pe conturi.','Verifică mapping pe angajat/centru cost/org și schemă; postează în clonă și reconciliază.','A07 urmărește plata netă700/obligații; A05/A03 verifică manopera alocată operațiilor G2.','Reexecută autojob și UI pe același stat, apoi rectifică/stornează conform politicii.'],['Nota contabilă reflectă exact statul validat; netul700 și obligațiile300 se reconciliază cu brutul1000 în fixture.','Costul salarial recunoscut și alocarea manoperei sunt distincte: alocarea100 nu produce a doua cheltuială100 fără justificare contabilă.','Un singur set economic activ per stat/versiune; drepturile și auditul rectificării sunt păstrate.'],['Stat nefinalizat; cont lipsă; două note pentru același payroll; plată înainte de validare; schimbare org; retry după timeout.'],['Native payroll posting dacă pluginul instalat îl oferă','MJournal/Fact_Acct','native allocation/cost dimensions'], 'Butoane separate calcul/validare/înregistrare/plată; afișarea legăturii stat–notă–plată și a costului alocat.', ['A03-A05','A03-A07','A03-A02','A03-A09']);
add(27,'REGES și HR: evenimente datate, impact salarial, fără transmisii',['P01.C07'],['A03.PL05','A03.PL10'],['process/RegesFlux.java','form/WEvaRegesAplicatieForm.java','form/WEvaRegesForm.java','documente/TemeiReges.java','form/RegesContractDialog.java'],['EVA: contract/eveniment/registru REGES de inventariat','AD_PInstance','AD_Attachment'],['Angajare, modificare, suspendare/reluare și încetare pentru persoană sintetică; corecție retroactivă în lună deja calculată.'],['Identifică cronologia legală și contractul local HR→payroll, cu surse oficiale verificate la execuție.','Urmărește modificarea locală, documentul justificativ și efectul în calculul salariului/perioadei.','Simulează acceptare/respins/timeout REGES prin mock, fără niciun apel extern de scriere.','Testează drepturi, câmpuri obligatorii, versiuni corecție și export minimizat.'],['Datele și starea contractuală folosite de payroll sunt cele valabile pentru perioada calculată.','Acceptarea externă nu este dedusă din salvarea locală; fiecare eveniment are statut și dovadă distincte.','Corecția retroactivă semnalizează salariile/declarațiile afectate; zero PII reală și zero transmisii externe.'],['Evenimente în ordine greșită; intervale suprapuse; retroactiv după închidere; duplicate; acces neautorizat; temei lipsă.'],['Native employee/business-partner identity după inventar','EVA HR/REGES existent; nicio nouă identitate paralelă'], 'Flux ghidat cu cronologie și impact; utilizatorul nu confundă corecție, modificare și radiere.', ['A03-A01','A03-A02','A03-A09','A03-A10']);
add(28,'Active: intrare, amortizare contabilă/fiscală și registru',['P01.C08'],['A03.PL06'],['process/AmortizareImobilizari.java','fiscal/AmortizareFiscala.java','form/WImobilizariForm.java'],['A_Asset','A_Asset_Addition','A_Depreciation_Workfile','A_Depreciation_Exp','Fact_Acct','C_Invoice'],['Activ achiziționat1200, durată12 luni și valoare reziduală0 pentru scenariul sintetic, data punerii în funcțiune distinctă; metodă fiscală diferită dacă permisă oficial.'],['A04 livrează factura/recepția și valoarea capitalizată; verifică utilizarea obiectelor native A_Asset.','Calculează independent planul contabil/fiscal și momentul începerii conform regulii aplicabile.','Generează amortizare în clonă, postează și reconciliază registrul cu Fact_Acct; repetă luna.','Testează modificare durată/valoare, lună parțială și schemă contabilă secundară.'],['Amortizarea sintetică liniară este100 pe lună completă unde ipoteza se aplică; ultimul interval închide exact valoarea amortizabilă.','Amortizarea fiscală și contabilă sunt raportate distinct; nu dublează cheltuiala.','O singură amortizare economică activă per activ/schemă/perioadă; valoarea netă nu devine negativă fără regulă explicită.'],['Dată serviciu lipsă; durată0; activ de alt client; retry; asset inactiv/disposed; cont lipsă; perioadă închisă.'],['A_Asset','A_Depreciation_Workfile/Exp','native asset posting; EVA strat fiscal separat justificat'], 'Fișă activ cu cronologie, valoare brută/amortizare/net, contabil versus fiscal și documentele sursă.', ['A03-A04','A03-A02','A03-A09']);
add(29,'Active: ieșire, casare, vânzare, anulare și import istoric',['P01.C08','P01.C11'],['A03.PL06'],['process/AmortizareImobilizari.java','fiscal/AmortizareFiscala.java','form/WImobilizariForm.java','anaf/GenD406.java'],['A_Asset','A_Asset_Disposed','A_Depreciation_Exp','C_Invoice','Fact_Acct'],['Activ1200 amortizat800, valoare netă400; casare/vânzare la dată intermediară; activ preluat deja casat și un activ complet amortizat încă folosit.'],['Verifică cronologia intrare/amortizare/ieșire și documentele native efective.','Calculează independent valoarea netă și rezultatul ieșirii; urmărește conturile și registrele.','Anulează/reversează în clonă, fără ștergere istoric; reexecută amortizarea după ieșire.','Verifică activele preluate din import și SAF-T pentru dublare/reîncepere amortizare.'],['Ieșirea scoate exact valoarea brută/amortizarea acumulată și tratează netul400 conform regulii aplicabile.','Activul casat nu primește amortizare nouă; complet amortizat dar utilizat nu dispare nejustificat din registru.','Reversarea restabilește corect starea/valoarea și păstrează documentele inițiale.'],['Casare dublă; vânzare înainte de intrare; asset importat disposed dar IsActive; schimbare dată după închidere; scădere sub zero.'],['A_Asset_Disposed','native reversal/asset posting','EVA registru fiscal unde necesar'], 'Acțiuni clare casare/vânzare/corecție, cu impact previzualizat; activul istoric rămâne consultabil.', ['A03-A04','A03-A02','A03-A09']);
add(30,'Pornire firmă și import SAGA: solduri, cutover și reconciliere',['P01.C11','P01.C01','P01.C03','P01.C04','P01.C08'],['A03.PL07','A03.PL01','A03.PL03','A03.PL06'],['fiscal/SoldTvaNeexigibilPreluat.java','fiscal/MotorStraturi.java','date/BalantaService.java','process/ReglareTvaNeexigibilaPreluat.java'],['GL_Journal','Fact_Acct','C_Invoice','C_Payment','A_Asset','M_CostDetail','EVA: tabele staging import A04 de inventariat'],['Solduri debit/credit echilibrate, facturi deschise1000, TVA neexigibilă, stoc10 și activ net400 la aceeași dată cutover; fișier duplicat și fișier corectat.'],['A04 fixează exportul original/hash, data cutover, mapping și totalurile de control.','Compară solduri importate cu documentele deschise și registrele auxiliare fără a le dubla în GL.','Execută în clonă import controlat, retry și corecție; urmărește staging→PO→postare.','Reconciliază bilanț/parteneri/stoc/active/TVA înainte și după prima operație din noua perioadă.'],['100% totalurilor de control explicate; facturi deschise, stock și active corespund soldurilor GL.','Același fișier nu produce a doua preluare; corecția nu șterge neauditabil originalul.','Prima tranzacție nouă nu recunoaște încă o dată venitul/costul/TVA deja preluat.'],['Encoding/decimale; chei duplicate; CUI alt client; cont lipsă; an diferit; staging parțial; import repetat presupus upsert.'],['Native import/staging/document PO unde disponibil','GL_Journal/native balances','EVA import existing'], 'Wizard cu preview, erori pe rând și totaluri înainte de aplicare; rezultatul indică importat versus postat și ce rămâne de corectat.', ['A03-A04','A03-A02','A03-A05','A03-A07','A03-A09']);
add(31,'Audit trail, monografie și dovadă regenerabilă',['P01.C09','P01.C12','P01.C16'],['A03.PL01','A03.PL04','A03.PL09'],['audit/JurnalAudit.java','monografie/JurnalDosar.java','documente/RegistruDocumente.java','anaf/RegistruDeclaratii.java','component/EvaAuditPostareEvents.java'],['AD_ChangeLog','AD_PInstance','AD_Attachment','Fact_Acct','EVA: registre audit/documente de inventariat'],['Document creat/modificat/completat/postat/reversat, declarație regenerată și utilizator cu citire; atașament cu hash original.'],['Corelează actor/timp/versiune/firmă și ID sursă în UI/proces/document/posting/export.','Verifică retenția originalului și diferențele între versiuni, fără expunere de secrete sau PII.','Regenerează un raport din aceeași versiune/date și explică toate câmpurile nedeterministe.','Testează acces la audit și export, plus comportamentul dacă logarea eșuează.'],['Fiecare efect material are document sursă, actor și proveniență; exportul indică perioada/schema/versiunea.','Reversarea nu șterge urma inițială; hashurile permit detectarea modificării artefactului.','Lipsa logului nu devine automat dovada lipsei operației; se investighează toate straturile.'],['Log de alt client; timestamp fără fus; export modificat; atașament lipsă; duplicat; operație async fără correlation ID.'],['AD_ChangeLog','AD_PInstance','AD_Attachment','Fact_Acct source keys'], 'Contabilul poate merge din raport la document, notă și istoric în pași expliciți; termenii sunt constanți.', ['A03-A01','A03-A02','A03-A09','A03-A12']);
add(32,'Meniuri, drepturi, setări și experiență contabilă completă',['P01.C01','P01.C02','P01.C03','P01.C04','P01.C05','P01.C06','P01.C07','P01.C08','P01.C09','P01.C10','P01.C11','P01.C12','P01.C13','P01.C14','P01.C15','P01.C16','P01.C17','P01.C18','P01.C19','P01.C20'],['A03.PL01','A03.PL04','A03.PL05','A03.PL06','A03.PL09'],['form/WBalantaForm.java','form/WDeclaratiiForm.java','form/WSagaHartaDeclaratiiForm.java','form/WSagaGhidInchidereForm.java','form/WSagaConfigSalariiForm.java','form/WImobilizariForm.java'],['AD_Menu','AD_TreeNodeMM','AD_Form','AD_Window','AD_Process','AD_Role','AD_Process_Access','AD_Window_Access'],['Rol contabil, gestionar fără postare, revizor și administrator; 1920×1080 și1366×768; tastatură; mobil prin A09 și titularii aplicațiilor.'],['A09 inventariază toate meniurile și setările actuale; A03 leagă cele20capitole de activitățile contabile și trecerile către WMS/comenzi/canale.','Parcurge fiecare flux critic de la meniu la rezultat și recuperare; verifică stări empty/loading/error/timeout/partial/success.','Verifică denumiri/perioadă/firmă, selecții incompatibile, setări obligatorii și protecția server-side.','Testează 2–3 operații succesive pe același obiect, schimbare context și revenire; validează citirea tastatură/focus/contrast cu A09.'],['Nicio funcție contabilă existentă identificată nu este omisă din inventar fără dispoziție; fiecare setare are scop, domeniu, default și validare.','Separarea WMS/gestiuni/comenzi/canale nu ascunde documentele contabile și nu permite configurări incompatibile tacit.','Succesul vizual este confirmat în DB; butonul ascuns nu ține loc de autorizare.','Mobilul nu primește PASS prin citirea ecranului desktop; suprafețele indisponibile rămân NEEXECUTAT.'],['Rol fără drept de postare; perioadă greșită; dropdown de altă firmă; loading infinit; dublu click; mesaj tehnic; pierdere input la eroare.'],['Native AD_Menu/Window/Process/access','AD validation/reference/callout; adaptare form EVA existent'], 'Lista de verificare UX se execută la ambele rezoluții; pașii sunt inteligibili pentru utilizator cu bază contabilă și iDempiere, cu termen explicat și acțiune următoare.', ['A03-A09','A03-A01','A03-A02','A03-A05','A03-A06']);
add(33,'Export/PDF/registre și performanță pe volume reale sintetice',['P01.C01','P01.C09','P01.C14','P01.C15'],['A03.PL01','A03.PL04'],['form/FacturaTipar.java','form/WSagaRegistruInventarPatrimForm.java','trezorerie/RegistruCasaTipar.java','process/RegistruJurnal.java','date/BalantaService.java'],['Fact_Acct','C_Invoice','AD_PrintFormat','AD_PrintFormatItem','AD_PInstance'],['Fixture20 documente pentru verificare manuală, 100000 linii Fact_Acct pentru raport și1000000 pentru stres separat; diacritice, text lung, valori negative, monede.'],['Fixează hardware/memorie/DB/indexuri/cache și buget de referință cu A10 înainte de măsurare.','Compară rânduri/totaluri UI/export/PDF, deschide PDF-ul și inspectează toate paginile fixture-ului mic și extremitățile/lipsurile volumului mare.','Măsoară 5 repetări reci și5calde, mediană/p95/memorie/query plan, cu2 și5 sesiuni concurente; păstrează primul eșec.','Testează timeout/anulare/export în fundal și verifică fișierul incomplet, formula injection în export text și accesul la linkul generat.'],['Totaluri și cardinalități identice pentru același snapshot/filtru; zero pagini/linii trunchiate ori diacritice pierdute.','Buget provizoriu explicit: deschidere/filtrare raport100k≤5s p95, export100k≤60s și anulare vizibilă≤2s; A10 validează mediul/bugetul înaintea probei; abaterile sunt raportate, nu relaxate retroactiv.','Stres1m are obiectiv măsurare limită și recuperare, fără presupunerea aceluiași SLA; nu blochează alte firme/sesiuni.'],['Pagination double-count; cache date vechi; pagină finală lipsă; Excel formula prefix; export alt client; memorie insuficientă; job întrerupt.'],['Native print/report engine','AD_PrintFormat','native read-only reporting; streaming EVA dacă existent'], 'Export cu progres, perioadă și context; fișier incomplet marcat; focus și controale disponibile în timpul procesării.', ['A03-A02','A03-A09','A03-A10']);
add(34,'Bugete, angajamente și comparație realizat–buget',['P01.C01','P01.C02','P01.C12'],['A03.PL01','A03.PL09'],['date/BalantaService.java','process/BalantaAnalitica.java','monografie/JurnalDosar.java'],['GL_Budget','GL_Journal','GL_JournalLine','Fact_Acct','C_AcctSchema'],['Buget1000, realizat700 și angajament200 pe aceeași dimensiune; două versiuni buget și o realocare între perioade.'],['Inventariază mecanismul efectiv de buget și PostingType în native/config/EVA; nu presupune un ecran din numele tabelului.','Urmărește versiune buget/dimensiuni/perioade și formula raportului comparativ.','Verifică separarea actual/budget/commitment în agregări, balanță și bilanț.','Testează modificare/revizie și drepturi, fără rescrierea istoriei realizatului.'],['Realizatul contabil rămâne700, nu1700/1900 prin însumarea bugetului/angajamentului.','Disponibilul după regula configurată este explicit:1000−700=300 sau1000−700−200=100 când angajamentul este inclus; raportul spune care.','Fiecare versiune/dimensiune este trasabilă; N/A numai după inventar și acceptA11, nu prin omisiune.'],['PostingType omis; buget altă schemă; dublare angajament după facturare; comparație versiuni diferite; drepturi de modificare.'],['GL_Budget','Fact_Acct PostingType','native budget/commitment reporting dacă disponibil'], 'Etichete clare buget/angajat/realizat/disponibil și versiune; drill-down al diferențelor.', ['A03-A02','A03-A06','A03-A09']);
add(35,'Regresie contabilă la modificări DB/migrare/backfill',['P01.C11','P01.C13','P01.C15','P01.C16'],['A03.PL01','A03.PL04','A03.PL09'],['component/EvaAuditPostareEvents.java','fiscal/JurnalVersiuniModel.java','audit/JurnalAudit.java','@Documentatie/echipa-2026-10-09/00_REGULI_TESTARE.md'],['AD_Table','AD_Column','AD_ChangeLog','Fact_Acct','GL_Journal','EVA: registru migrații instalat de inventariat A02'],['Snapshot înainte/după migrarea relevantă; cliențiA/B, documente istorice și nepostate; întrerupere la mijlocul backfill-ului și retry numai în clonă.'],['A02 livrează lista migration/DDL/backfill aplicabile și dovada versiunii instalate; A03 definește solduri/chei/totaluri invariabile.','Compară constrângeri/indecși și tabele AD cu schema reală; urmărește impactul fiscal/contabil.','Reexecută migrarea doar în mediu de test aprobat și repetă pipeline-urile afectate, nu întreaga suită fără motiv.','A10 verifică clean build/reproducibilitate și izolarea; A03 păstrează distinct probele citite vs executate.'],['Soldurile/documentele istorice se păstrează dacă migrarea nu are transformare explicită aprobată; schimbările au reconciliere completă.','Reexecutarea/backfill-ul nu duplică și nu traversează clienți; schema instalată nu este dedusă din SQL în Git.','Zero test declarat trecut fără comandă/timp/log/fixture și versiune.'],['Migrare parțială; coloana există dar AD lipsește; backfill pe alt client; index unic absent; date istorice incompatibile.'],['AD migration/model mechanisms','native constraints/posting contracts; extindere minimă'], 'După migrare, aceleași acțiuni contabile și meniuri rămân utilizabile; erori de configurare explicite, nu succes gol.', ['A03-A02','A03-A10','A03-A09']);
add(36,'Acoperirea fiecărui task finalizat și închiderea auditului',['P01.C01','P01.C02','P01.C03','P01.C04','P01.C05','P01.C06','P01.C07','P01.C08','P01.C09','P01.C10','P01.C11','P01.C12','P01.C13','P01.C14','P01.C15','P01.C16','P01.C17','P01.C18','P01.C19','P01.C20'],['A03.PL01','A03.PL02','A03.PL03','A03.PL04','A03.PL05','A03.PL06','A03.PL07','A03.PL08','A03.PL09','A03.PL10'],['@Documentatie/echipa-2026-10-09/00_STATUS_TASKURI.json','@Documentatie/echipa-2026-10-09/00_STATUS_FINALIZATE.json','@Documentatie/echipa-2026-10-09/00_CORESPONDENTA_COD_CAPITOL.json','@Documentatie/echipa-2026-10-09/00_CHECKLIST_DEFECTE.json'],['AD_Menu','AD_Process','AD_Form','AD_Table','Fact_Acct'],['Inventar P01 actual din portal capturat de titular, export Git istoric separat; toate criteriile taskurilor finalizate cu impact contabil.'],['A12 reconciliază total sursă/extras/paginat/finalizat și aliasurile în P01.Cxx.Tnnnn; A03 primește fiecare criteriu contabil.','Leagă bidirecțional cerință→control→pipeline→cod/UI/DB→probă→constatare→reviewA11.','Verifică toate defectele/analizele istorice aplicabile la SHA actual fără a le declara automat încă prezente.','Predă raportul și dovezile; A11 reproduce criticile și respinge lacunele; reia exclusiv verificările insuficiente/regresia afectată cu istoric păstrat.'],['Numitorul taskurilor/criteriilor contabile este cunoscut și reconciliat; zero criterii fără dispoziție și zero taskuri finalizate declarate auditate doar din status/commit.','Raportul separă PASS/FAIL/NEEXECUTAT/INCONCLUDENT și static/runtime/live; lipsa accesului nu devine PASS sau10/10.','A11 acordă independent scorul calității auditului pentru hashul exact; defectele produsului rămân distincte de nota auditului.'],['T0001 ambiguu fără capitol; criteriu ascuns în subtask; status schimbat în timpul auditului; istoric cu SHA vechi; eșec omis după rerun.'],['Native/configured/installed/executed/accepted sunt niveluri separate pentru fiecare criteriu'], 'Raportul final folosește obiectiv, unde/cum/când, pași și explicație pe înțelesul contabilului; linkuri la dovezi și limite clare.', ['A03-A12','A03-A11','A03-A09']);

const pipelines=[];
function pl(n,title,actor,input,ui,files,po,db,normal,negative,invariants,final,owners,ck){const id='A03.PL'+String(n).padStart(2,'0');pipelines.push({pipeline_id:id,business_outcome:title,trigger:'Acțiune explicită UI/proces/job configurat în clonă; nu executat în faza plan.',actor_context:actor,input_contract:input,state_machine:'Ciornă/validare→pregătire→completare→postare→reconciliere; stările concrete DocStatus/Posted și registrele se identifică la audit. Non-CO, CO nepostat, respins și timeout rămân distincte.',ui_route:ui,api_calls:'AD_Process/AD_PInstance, handler form și/sau endpoint EVA efectiv se inventariază și citează exact după gate; nicio rută inventată din numele clasei.',service_symbols:refs(files),po_layer:po,db_reads_writes:db,native_documents:po,external_effects:'INTERZISE: ANAF/SPV/REGES/bancă/marketplace/curier/refund extern. Mock numai, garda și egress blocat. Interogare live permisă doar read-only și minimizată.',transaction_boundaries:'Captură înainte; intrare UI/API; transaction native PO/DocAction; commit; postare dacă async; raport. Verifică atomicitate pe fiecare etapă, IDurile persistate și reluarea după cădere între commit și răspuns.',correlation_ids:['AD_Client_ID','AD_Org_ID','C_AcctSchema_ID','AD_PInstance_ID','AD_Table_ID','Record_ID','Line_ID','UUID/operation_id dacă există','posting/run/export ID'],authorization_guards:'Client/org/schemă/rol și document permise pe server la fiecare intrare; UI nu reprezintă control suficient.',idempotency_scope:'Se identifică cheia reală document/operație+client+schemă+versiune/perioadă după natura fluxului; se verifică constrângerea/lockingul, nu numai butonul dezactivat.',normal_path:normal,negative_paths:negative,retry_timeout_concurrency:'2–3 operații succesive pe același obiect, duplicate simultane din2sesiuni, timeout după commit și evenimente inversate; fără retry orb la efect ambiguu.',compensation_reconciliation:'Reversare documentară nativă/corecție auditabilă conform politicii; nu ște