package com.eva.ro.contab.date;

import java.math.BigDecimal;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Timestamp;
import java.util.ArrayList;
import java.util.List;

import org.compiere.util.DB;

/**
 * Calculul balanței de verificare — SURSĂ UNICĂ pentru proces și pentru ecran.
 *
 * DE CE EXISTĂ CLASA ASTA: aceeași balanță se cere din două locuri —
 *   • procesul {@code EVA_Balanta}, care o tipărește în jurnalul de proces;
 *   • ecranul ZK {@code WBalantaForm}, care o afișează ca tabel sortabil.
 * Dacă fiecare și-ar avea interogarea proprie, ar diverge la prima modificare și ai avea două
 * balanțe care nu se potrivesc — exact tipul de defect care se descoperă în fața unui control.
 * Aici e un singur `SELECT`, folosit de amândouă.
 *
 * STRICT READ-ONLY. Soldurile se calculează pe moneda funcțională (`amtacct*`), `postingtype='A'`.
 */
public final class BalantaService {

    private BalantaService() { }

    /** Un rând de balanță, cu cele patru perechi de coloane. */
    public static final class Rand {
        public String simbol;
        public String denumire;
        /** sold inițial NET (>0 debitor, <0 creditor) */
        public BigDecimal si = BigDecimal.ZERO;
        public BigDecimal rulajD = BigDecimal.ZERO;
        public BigDecimal rulajC = BigDecimal.ZERO;

        public BigDecimal siD()  { return si.signum() > 0 ? si : BigDecimal.ZERO; }
        public BigDecimal siC()  { return si.signum() < 0 ? si.negate() : BigDecimal.ZERO; }
        public BigDecimal totalD() { return siD().add(rulajD); }
        public BigDecimal totalC() { return siC().add(rulajC); }
        public BigDecimal sfNet()  { return totalD().subtract(totalC()); }
        public BigDecimal sfD()  { return sfNet().signum() > 0 ? sfNet() : BigDecimal.ZERO; }
        public BigDecimal sfC()  { return sfNet().signum() < 0 ? sfNet().negate() : BigDecimal.ZERO; }
        public boolean gol() {
            return si.signum() == 0 && rulajD.signum() == 0 && rulajC.signum() == 0;
        }
    }

    /** Totalurile și verdictul celor patru egalități. */
    public static final class Total {
        public BigDecimal siD = BigDecimal.ZERO, siC = BigDecimal.ZERO;
        public BigDecimal ruD = BigDecimal.ZERO, ruC = BigDecimal.ZERO;
        public BigDecimal tsD = BigDecimal.ZERO, tsC = BigDecimal.ZERO;
        public BigDecimal sfD = BigDecimal.ZERO, sfC = BigDecimal.ZERO;

        private static boolean egal(BigDecimal a, BigDecimal b) {
            return a.subtract(b).abs().compareTo(new BigDecimal("0.005")) < 0;
        }
        public boolean egalitateSolduriInitiale() { return egal(siD, siC); }
        public boolean egalitateRulaje()          { return egal(ruD, ruC); }
        public boolean egalitateTotalSume()       { return egal(tsD, tsC); }
        public boolean egalitateSolduriFinale()   { return egal(sfD, sfC); }
        /** Cele patru egalități ale balanței de verificare — toate trebuie să țină. */
        public boolean echilibrata() {
            return egalitateSolduriInitiale() && egalitateRulaje()
                && egalitateTotalSume() && egalitateSolduriFinale();
        }
    }

    /**
     * Citește balanța pentru interval.
     *
     * @param toateConturile dacă {@code false}, sar conturile fără nicio mișcare și fără sold
     * @param trxName        tranzacția curentă (poate fi null)
