    public static List<Rand> incarca(int clientId, Timestamp de, Timestamp pana, int orgId,
                                     boolean toateConturile, String trxName) throws Exception {
        String sql =
                "SELECT ev.value, ev.name, "
              + "  SUM(CASE WHEN f.dateacct <  ? THEN f.amtacctdr - f.amtacctcr ELSE 0 END) AS si, "
              + "  SUM(CASE WHEN f.dateacct >= ? AND f.dateacct <= ? THEN f.amtacctdr ELSE 0 END) AS ru_d, "
              + "  SUM(CASE WHEN f.dateacct >= ? AND f.dateacct <= ? THEN f.amtacctcr ELSE 0 END) AS ru_c "
              + "FROM fact_acct f "
              + "JOIN c_elementvalue ev ON ev.c_elementvalue_id = f.account_id "
              + "WHERE f.ad_client_id = ? AND f.postingtype = 'A' AND f.dateacct <= ? "
              + (orgId > 0 ? "  AND f.ad_org_id = " + orgId + " " : "")
              + "GROUP BY ev.value, ev.name ORDER BY ev.value";

        List<Rand> out = new ArrayList<>();
        PreparedStatement ps = null;
        ResultSet rs = null;
        try {
            ps = DB.prepareStatement(sql, trxName);
            int k = 1;
            ps.setTimestamp(k++, de);
            ps.setTimestamp(k++, de);
            ps.setTimestamp(k++, pana);
            ps.setTimestamp(k++, de);
            ps.setTimestamp(k++, pana);
            ps.setInt(k++, clientId);
            ps.setTimestamp(k++, pana);
            rs = ps.executeQuery();
            while (rs.next()) {
                Rand r = new Rand();
                r.simbol = rs.getString(1);
                r.denumire = rs.getString(2);
                r.si = nz(rs.getBigDecimal(3));
                r.rulajD = nz(rs.getBigDecimal(4));
                r.rulajC = nz(rs.getBigDecimal(5));
                if (r.gol() && !toateConturile)
                    continue;
                out.add(r);
            }
        } finally {
            DB.close(rs, ps);
        }
        return out;
    }

    /** Totalurile pe o listă de rânduri. */
    public static Total totalizeaza(List<Rand> randuri) {
        Total t = new Total();
        for (Rand r : randuri) {
            t.siD = t.siD.add(r.siD());   t.siC = t.siC.add(r.siC());
            t.ruD = t.ruD.add(r.rulajD);  t.ruC = t.ruC.add(r.rulajC);
            t.tsD = t.tsD.add(r.totalD()); t.tsC = t.tsC.add(r.totalC());
            t.sfD = t.sfD.add(r.sfD());   t.sfC = t.sfC.add(r.sfC());
        }
        return t;
    }

    private static BigDecimal nz(BigDecimal b) { return b == null ? BigDecimal.ZERO : b; }

    // ───────────────────────────────────────────── formularul 14-6-30 (T16 A-09): conturi SINTETICE, perechi D–C

    /**
     * Un cont SINTETIC din balanța de verificare (14-6-30): solduri inițiale ({@code siAn} = soldul de la începutul perioadei
     * în varianta cu 4 egalități) / rulajele perioadei / total sume / solduri finale — fiecare pereche debit–credit; varianta
     * cu 5 perechi adaugă «sume precedente» (1 ianuarie … ziua dinaintea perioadei).
     */
    public static final class RandSaga {
        public String simbol;
        public String denumire;
        /** sold inițial NET al anului (>0 debitor, <0 creditor) */
        public BigDecimal siAn = BigDecimal.ZERO;
        public BigDecimal precD = BigDecimal.ZERO, precC = BigDecimal.ZERO;
        public BigDecimal ruD = BigDecimal.ZERO, ruC = BigDecimal.ZERO;

        public BigDecimal siAnD() { return siAn.signum() > 0 ? siAn : BigDecimal.ZERO; }
        public BigDecimal siAnC() { return siAn.signum() < 0 ? siAn.negate() : BigDecimal.ZERO; }
        public BigDecimal tsD() { return siAnD().add(precD).add(ruD); }
        public BigDecimal tsC() { return siAnC().add(precC).add(ruC); }
        public BigDecimal sfNet() { return tsD().subtract(tsC()); }
        public BigDecimal sfD() { return sfNet().signum() > 0 ? sfNet() : BigDecimal.ZERO; }
        public BigDecimal sfC() { return sfNet().signum() < 0 ? sfNet().negate() : BigDecimal.ZERO; }
        /** Clasa contului (prima cifră). */
        public String clasa() { return simbol == null || simbol.isEmpty() ? "" : simbol.substring(0, 1); }

        public void aduna(RandSaga o) {
            siAn = siAn.add(o.siAn);
            precD = precD.add(o.precD);
            precC = precC.add(o.precC);
            ruD = ruD.add(o.ruD);
            ruC = ruC.add(o.ruC);
        }
    }

    /**
     * Compune balanța SAGA din cele două citiri ale serviciului: {@code perioada} = [început perioadă … sfârșit]
     * ({@code si} = soldul de dinainte de perioadă, rulajele perioadei) și {@code precedente} = [1 ianuarie … ziua
     * dinaintea perioadei] ({@code si} = soldul de la 1 ianuarie = solduri inițiale an, rulajele = sume precedente);
     * {@code precedente} gol când perioada începe pe 1 ianuarie. Conturile analitice se adună pe sinteticul lor
     * (simbolul până la primul «.»); rezultatul e sortat după cont. Pur.
     */
    public static List<RandSaga> compune(List<Rand> perioada, List<Rand> precedente) {
        java.util.Map<String, Rand> prec = new java.util.HashMap<>();
        for (Rand r : precedente)
            prec.put(r.simbol, r);
        java.util.Map<String, RandSaga> sint = new java.util.TreeMap<>();
        java.util.Map<String, String> nume = new java.util.HashMap<>();
        for (Rand p : perioada) {
            String cheie = p.simbol == null ? "" : p.simbol;
            int pct = cheie.indexOf('.');
            if (pct > 0)
                cheie = cheie.substring(0, pct);
            RandSaga x = new RandSaga();
            x.simbol = cheie;
            Rand pr = prec.get(p.simbol);
            // fără citire precedentă (perioada începe la 1 ianuarie sau contul n-avea mișcare înainte):
            // soldul de dinainte de perioadă e și soldul inițial al anului
            x.siAn = pr != null ? pr.si : p.si;
            if (pr != null) {
                x.precD = pr.rulajD;
                x.precC = pr.rulajC;
            }
            x.ruD = p.rulajD;
            x.ruC = p.rulajC;
            RandSaga acc = sint.get(cheie);
            if (acc == null) {
                sint.put(cheie, x);
                acc = x;
            } else
                acc.aduna(x);
            // denumirea: a contului sintetic însuși; altfel a primului analitic întâlnit
            if (p.simbol != null && p.simbol.equals(cheie) || !nume.containsKey(cheie))
                nume.put(cheie, p.denumire);
        }
        List<RandSaga> out = new ArrayList<>();
        for (RandSaga r : sint.values()) {
            r.denumire = nume.get(r.simbol);
            out.add(r);
        }
        return out;
    }

    /**
     * Balanța de verificare conform formularului 14-6-30 (OMFP 2634/2015), cu 4 egalități: pe conturi SINTETICE,
     * solduri inițiale (la începutul perioadei) / rulaje (perioadă) / total sume / solduri finale, fiecare D–C. Rânduri
     * fără sold și fără mișcare se sar. ({@link #compune} acceptă și varianta cu sume precedente — 5 perechi.)
     */
    public static List<RandSaga> incarca14630(int clientId, Timestamp de, Timestamp pana, String trxName) throws Exception {
        List<RandSaga> out = new ArrayList<>();
        for (RandSaga r : compune(incarca(clientId, de, pana, 0, true, trxName), new ArrayList<>()))
            if (r.tsD().signum() != 0 || r.tsC().signum() != 0 || r.sfNet().signum() != 0)
                out.add(r);
        return out;
    }

    /**
     * Capitalul social subscris la sfârșitul intervalului: soldul creditor al conturilor 1011 + 1012 (și analiticele
     * lor), din contabilitate; {@code 0} dacă nu există.
     */
    public static BigDecimal capitalSocial(int clientId, Timestamp pana, String trxName) throws Exception {
        String sql = "SELECT COALESCE(SUM(f.amtacctcr - f.amtacctdr),0) FROM fact_acct f"
                + " JOIN c_elementvalue ev ON ev.c_elementvalue_id=f.account_id"
                + " WHERE f.ad_client_id=? AND f.postingtype='A' AND f.dateacct<=?"
                + " AND (ev.value IN ('1011','1012') OR ev.value LIKE '1011.%' OR ev.value LIKE '1012.%')";
        try (PreparedStatement ps = DB.prepareStatement(sql, trxName)) {
            ps.setInt(1, clientId);
            ps.setTimestamp(2, pana);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() && rs.getBigDecimal(1) != null ? rs.getBigDecimal(1) : BigDecimal.ZERO;
            }
        }
    }
