    /** Implementarea comună: {@code deLa} lipsă înseamnă „de la începutul evidenței". */
    private static Map<String, BigDecimal> net(int client, String[] tipare,
            Timestamp deLa, Timestamp panaLa, String trxName) throws Exception {
        StringBuilder unde = new StringBuilder("(");
        for (int i = 0; i < tipare.length; i++)
            unde.append(i == 0 ? "" : " OR ").append("ev.value LIKE ?");
        unde.append(")");
        String sql = "SELECT ev.value, SUM(f.amtacctdr - f.amtacctcr)"
                + " FROM fact_acct f JOIN c_elementvalue ev ON ev.c_elementvalue_id=f.account_id"
                + " WHERE f.ad_client_id=? AND f.postingtype=? AND " + unde
                + (deLa == null ? " AND f.dateacct <= ?" : " AND f.dateacct BETWEEN ? AND ?")
                + " GROUP BY ev.value HAVING ABS(SUM(f.amtacctdr - f.amtacctcr)) >= 0.005"
                + " ORDER BY ev.value";
        Map<String, BigDecimal> net = new LinkedHashMap<>();
        try (PreparedStatement ps = DB.prepareStatement(sql, trxName)) {
            int k = 1;
            ps.setInt(k++, client);
            ps.setString(k++, ACTUAL);
            for (String t : tipare)
                ps.setString(k++, t);
            if (deLa != null)
                ps.setTimestamp(k++, deLa);
            ps.setTimestamp(k++, panaLa);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next())
                    net.put(rs.getString(1), rs.getBigDecimal(2));
            }
        }
        return net;
    }

    /**
     * Rulajul BRUT al perioadei: {@code [Σ debit, Σ credit]} peste conturile căutate. Netul
     * ({@link #rulaje}) nu spune dacă s-a mișcat ceva — o notă de închidere lasă contul cu net
     * zero, dar cu rulaj. Detecția „operația e deja făcută" are nevoie tocmai de rulaj.
     */
    public static BigDecimal[] rulajBrut(int client, String[] tipare, Timestamp deLa,
            Timestamp panaLa, String trxName) {
        StringBuilder unde = new StringBuilder("(");
        for (int i = 0; i < tipare.length; i++)
            unde.append(i == 0 ? "" : " OR ").append("ev.value LIKE ?");
        unde.append(")");
        String sql = "SELECT COALESCE(SUM(f.amtacctdr),0), COALESCE(SUM(f.amtacctcr),0)"
                + " FROM fact_acct f JOIN c_elementvalue ev ON ev.c_elementvalue_id=f.account_id"
                + " WHERE f.ad_client_id=? AND f.postingtype=? AND " + unde
                + (deLa == null ? " AND f.dateacct <= ?" : " AND f.dateacct BETWEEN ? AND ?");
        try (PreparedStatement ps = DB.prepareStatement(sql, trxName)) {
            int k = 1;
            ps.setInt(k++, client);
            ps.setString(k++, ACTUAL);
            for (String t : tipare)
                ps.setString(k++, t);
            if (deLa != null)
                ps.setTimestamp(k++, deLa);
            ps.setTimestamp(k++, panaLa);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next())
                    return new BigDecimal[]{rs.getBigDecimal(1), rs.getBigDecimal(2)};
            }
        } catch (Exception e) {
            // T58 eșec închis: semnalat evaluării în curs (InchidereLuna.Verificare) — pasul rămâne «nu se poate verifica»
            InchidereLuna.Verificare.eroare(e);
            // fără acces la bază, detecția se comportă ca „fără rulaj"
        }
        return new BigDecimal[]{BigDecimal.ZERO, BigDecimal.ZERO};
    }

